
"use strict";

document.querySelector(".formula").textContent="dxᵢ/dt = rᵢxᵢ(1 − xᵢ + Σⱼ≠ᵢ aᵢⱼxⱼ) − mᵢxᵢ + Dᵢ";
document.querySelector(".version").textContent="v3.4";
const dispersalOption=document.createElement("option");
dispersalOption.value="d";dispersalOption.textContent="Immigration Rate D";
document.getElementById("target").insertBefore(dispersalOption,document.querySelector('#target option[value="a"]'));
document.querySelectorAll("#fitPanel .fit-note")[0].innerHTML='<b>Fitting basis:</b> Mortality is represented as the independent loss term −mᵢxᵢ. Monoculture B₀, B(tₘ), K, and independently measured m are used to estimate growth rate r; stable pairwise-culture endpoints are then used to calculate aᵢⱼ. Intermediate measurement time tₘ: <input id="midTime" type="number" value="4" min="0.01"> h';
document.querySelectorAll("#fitPanel .fit-note")[1].innerHTML='<b>Experimental parameter definitions:</b><br><b>B₀</b>: initial measured biomass, in the same units as K.<br><b>B(tₘ)</b>: measured monoculture biomass at tₘ, used to fit r.<br><b>tₘ</b>: culture time at which B(tₘ) is measured, in h.<br><b>m</b>: independently measured mortality rate, in h⁻¹; mortality enters only as −mx.<br><b>K</b>: carrying capacity in the baseline environment without mortality and the normalization scale in B=Kx; with mortality, stable monoculture biomass is K(1−m/r).<br><b>r</b>: intrinsic growth rate in the growth term, in h⁻¹; r&gt;m is required.<br><b>D</b>: additive immigration from an external species pool, in normalized biomass·h⁻¹; set D=0 to recover the model without immigration. Fitting assumes D=0; D can be specified afterward for prediction.<br><b>Cᵢⱼ</b>: stable endpoint biomass of species i in pairwise coculture with species j.<br><b>aᵢⱼ</b>: dimensionless effect of species j on species i; positive values denote facilitation and negative values denote inhibition.';
document.querySelector("#fitResultPanel .subhead span").textContent="B₀, r, m, K  and  D";
document.querySelector("#fitPanel section .subhead span").textContent="Input B₀, B(tₘ), m and baseline  K";
document.querySelector(".method").innerHTML='Stability criterion: max |dxᵢ/dt| / max(1,x) &lt; <input id="tol" type="number" value="0.0001" step="0.00001" style="width:90px"> · Bᵢ = Kᵢxᵢ · Mortality Term = −mᵢxᵢ · Immigration Term = +Dᵢ';
const colors=["#d86d5b","#173f67","#c49a45","#73866b","#4d8c8a","#8d6d9f","#b85c86","#607d9d","#9b7048","#526b4f"];
const $=id=>document.getElementById(id),clamp=(v,l,h)=>Math.max(l,Math.min(h,v)),num=(id)=>Number($(id).value),fmt=(v,d=3)=>Number.isFinite(v)?v.toLocaleString("zh-CN",{maximumFractionDigits:d}):"—";
let N=5,mode="known",species=[],A=[],pairs=[],result=null,fitReady=false;
function gauss(){let u=0,v=0;while(!u)u=Math.random();while(!v)v=Math.random();return Math.sqrt(-2*Math.log(u))*Math.cos(2*Math.PI*v)}
function makeSpecies(n){return Array.from({length:n},(_,i)=>({name:`Species ${i+1}`,b0:+Math.max(.02,.1-i*.008).toFixed(3),g:+(.55+i%4*.1).toFixed(3),m:+(.04+i%3*.01).toFixed(3),k:+(.8+i%3*.2).toFixed(3),d:0,bMid:+(.45+i%3*.08).toFixed(3)}))}
function makeA(n){return Array.from({length:n},(_,i)=>Array.from({length:n},(_,j)=>{if(i===j)return-1;let z=Math.sin((i+1)*12.9898+(j+1)*78.233)*43758.5453;return+(((z-Math.floor(z))-.5)*.36).toFixed(3)}))}
function makePairs(){return species.map((si,i)=>species.map((sj,j)=>{let ci=Math.max(0,1-si.m/si.g),cj=Math.max(0,1-sj.m/sj.g);if(i===j)return+(ci*si.k).toFixed(3);let den=1-A[i][j]*A[j][i],x=Math.abs(den)<1e-8?.5:Math.max(.02,(ci+A[i][j]*cj)/den);return+(x*si.k).toFixed(3)}))}
function sync(){let root=mode==="known"?$("knownPanel"):$("fitPanel");if(mode==="known"){root.querySelectorAll("[data-s]").forEach(el=>{let i=+el.dataset.s,key=el.dataset.key;if(species[i])species[i][key]=key==="name"?el.value:Number(el.value)});root.querySelectorAll("[data-a]").forEach(el=>{let [i,j]=el.dataset.a.split(",").map(Number);if(i!==j&&A[i]&&j<A[i].length)A[i][j]=Number(el.value)})}else{root.querySelectorAll("[data-exp]").forEach(el=>{let i=+el.dataset.exp,key=el.dataset.key;if(species[i])species[i][key]=key==="name"?el.value:Number(el.value)});root.querySelectorAll("[data-p]").forEach(el=>{let [i,j]=el.dataset.p.split(",").map(Number);if(i!==j&&pairs[i]&&j<pairs[i].length)pairs[i][j]=Number(el.value)});if(fitReady){root.querySelectorAll("[data-frs]").forEach(el=>{let i=+el.dataset.frs,key=el.dataset.key;if(species[i])species[i][key]=key==="name"?el.value:Number(el.value)});root.querySelectorAll("[data-fra]").forEach(el=>{let [i,j]=el.dataset.fra.split(",").map(Number);if(i!==j&&A[i]&&j<A[i].length)A[i][j]=Number(el.value)})}}}
function validate(){if(!Number.isFinite(num("tMax"))||num("tMax")<=0)throw Error("Simulation duration must be greater than 0");if(!Number.isFinite(num("sample"))||num("sample")<=0)throw Error("Sampling interval must be greater than 0");species.forEach((s,i)=>{if(!s.name.trim())s.name=`Species ${i+1}`;if(!Number.isFinite(s.b0)||s.b0<0)throw Error(`${s.name}: initial biomass must be nonnegative`);if(!Number.isFinite(s.g)||s.g<=0)throw Error(`${s.name}: growth rate r must be greater than 0`);if(!Number.isFinite(s.m)||s.m<0)throw Error(`${s.name}: mortality rate m must be nonnegative`);if(s.g<=s.m)throw Error(`${s.name} must satisfy growth rate r > mortality rate m`);if(!Number.isFinite(s.k)||s.k<=0)throw Error(`${s.name}: carrying capacity K must be greater than 0`);if(!Number.isFinite(s.d)||s.d<0)throw Error(`${s.name}: immigration rate D must be nonnegative`)});A.forEach((r,i)=>r.forEach((v,j)=>{if(!Number.isFinite(v))throw Error(`Interaction coefficient a${i+1}${j+1} is not a valid number`)}))}
function speciesHTML(fit=false,resultTable=false){let attr=fit?"data-exp":resultTable?"data-frs":"data-s";return `<table><thead><tr><th>Species</th><th>Initial B₀</th>${fit?"<th>B(tₘ)</th>":""}<th>${fit?"fit Growth Rate r":"Growth Rate r"}</th><th>Mortality Rate m</th><th>Carrying Capacity K</th>${fit?"":"<th>Immigration Rate D</th>"}</tr></thead><tbody>${species.map((s,i)=>`<tr><td class="name"><input ${attr}="${i}" data-key="name" value="${s.name}"></td><td><input type="number" ${attr}="${i}" data-key="b0" value="${s.b0}" step=".01"></td>${fit?`<td><input type="number" ${attr}="${i}" data-key="bMid" value="${s.bMid}" step=".01"></td>`:""}<td><input type="number" ${attr}="${i}" data-key="g" value="${s.g}" step=".01" ${fit?"readonly":""}></td><td><input type="number" ${attr}="${i}" data-key="m" value="${s.m}" min="0" step=".01"></td><td><input type="number" ${attr}="${i}" data-key="k" value="${s.k}" step=".1"></td>${fit?"":`<td><input type="number" ${attr}="${i}" data-key="d" value="${s.d??0}" min="0" step="0.000001"></td>`}</tr>`).join("")}</tbody></table>`}
function matrixHTML(resultTable=false){let attr=resultTable?"data-fra":"data-a";return `<table class="matrix"><thead><tr><th></th>${species.map((_,i)=>`<th>S${i+1}</th>`).join("")}</tr></thead><tbody>${A.map((r,i)=>`<tr><th>S${i+1}</th>${r.map((v,j)=>{let bg=i===j?"#ead8cf":v>0?`rgba(23,63,103,${.08+Math.min(.75,Math.abs(v))*.5})`:`rgba(216,109,91,${.08+Math.min(.75,Math.abs(v))*.5})`;return`<td style="background:${bg}"><input type="number" ${attr}="${i},${j}" value="${v}" step=".01" ${i===j?"readonly":""}></td>`}).join("")}</tr>`).join("")}</tbody></table>`}
function pairHTML(){return `<table><thead><tr><th>Response species</th>${species.map((_,i)=>`<th>With S${i+1}</th>`).join("")}</tr></thead><tbody>${pairs.map((r,i)=>`<tr><th>S${i+1}</th>${r.map((v,j)=>`<td class="${i===j?"diag":""}"><input type="number" data-p="${i},${j}" value="${i===j?+(species[i].k*(1-species[i].m/species[i].g)).toFixed(3):v}" step=".01" ${i===j?"readonly":""}></td>`).join("")}</tr>`).join("")}</tbody></table>`}
function renderInputs(){$("speciesTable").innerHTML=speciesHTML();$("matrixTable").innerHTML=matrixHTML();$("fitSpeciesTable").innerHTML=speciesHTML(true);$("pairTable").innerHTML=pairHTML();$("fitResultSpecies").innerHTML=speciesHTML(false,true);$("fitResultMatrix").innerHTML=matrixHTML(true);$("fitResultPanel").classList.toggle("hidden",!fitReady)}
function deriv(x){return x.map((xi,i)=>{let b=1;for(let j=0;j<N;j++)b+=A[i][j]*x[j];return species[i].g*xi*b-species[i].m*xi+(species[i].d??0)})}
function rk4(x,h){let k1=deriv(x),k2=deriv(x.map((v,i)=>v+h*k1[i]/2)),k3=deriv(x.map((v,i)=>v+h*k2[i]/2)),k4=deriv(x.map((v,i)=>v+h*k3[i]));return x.map((v,i)=>clamp(v+h*(k1[i]+2*k2[i]+2*k3[i]+k4[i])/6,0,1e6))}
function simulate(){sync();validate();let tm=Math.max(1,num("tMax")),sample=Math.max(.05,num("sample")),tol=Math.max(1e-8,num("tol")),x=species.map(s=>Math.max(0,s.b0/s.k)),h=Math.max(.0005,Math.min(.05,sample/5,tm/3000)),t=0,next=sample,pts=[{t:0,b:x.map((v,i)=>v*species[i].k)}],stableStart=null,stableTime=null,window=Math.max(sample*3,Math.min(10,tm*.1)),warning="";while(t<tm-1e-10){let step=Math.min(h,tm-t);x=rk4(x,step);t+=step;if(x.some(v=>!Number.isFinite(v)||v>=999999)){warning="The system exhibited unbounded growth: Reduce positive Interactionsor reduce Initial Biomass";break}let d=deriv(x),ok=Math.max(...d.map(Math.abs))/Math.max(1,...x)<tol;if(ok){if(stableStart===null)stableStart=t;if(stableTime===null&&t-stableStart>=window)stableTime=stableStart}else stableStart=null;if(t+1e-8>=next||t+1e-8>=tm){pts.push({t:Math.min(t,tm),b:x.map((v,i)=>v*species[i].k)});next+=sample}}let end=x.map((v,i)=>v*species[i].k),sum=end.reduce((a,b)=>a+b,0),rel=end.map(v=>sum?v/sum:0);result={pts,end,rel,stableTime,warning};draw();setStatus(warning||"Simulation completed")}
function color(i){return colors[i%colors.length]}
function draw(){if(!result)return;drawLine();drawDonut();$("stableTime").textContent=result.stableTime===null?"Not reached":fmt(result.stableTime,2)+" h";$("legend").innerHTML=species.map((s,i)=>`<span><i style="background:${color(i)}"></i>${s.name}</span>`).join("");$("donutList").innerHTML=species.map((s,i)=>`<div><span><i style="display:inline-block;width:8px;height:8px;border-radius:50%;background:${color(i)};margin-right:4px"></i>${s.name}</span><b>${fmt(result.rel[i]*100,1)}%</b></div>`).join("");let mx=Math.max(...result.end,.01);$("bars").innerHTML=species.map((s,i)=>`<div class="bar"><span>${s.name}</span><div class="track"><i style="width:${Math.max(.5,result.end[i]/mx*100)}%;background:${color(i)}"></i></div><b>${fmt(result.end[i],4)}</b></div>`).join("")}
function drawLine(){let c=$("lineChart"),ctx=c.getContext("2d"),W=c.width,H=c.height,p={l:52,r:16,t:14,b:35},last=result.pts[result.pts.length-1],maxT=Math.max(1,last.t),maxB=Math.max(.1,...result.pts.flatMap(q=>q.b))*1.08,X=t=>p.l+t/maxT*(W-p.l-p.r),Y=v=>H-p.b-v/maxB*(H-p.t-p.b);ctx.clearRect(0,0,W,H);ctx.font="10px Arial";ctx.fillStyle="#666";ctx.strokeStyle="#ddd6ca";ctx.lineWidth=1;for(let k=0;k<5;k++){let v=maxB*k/4,y=Y(v);ctx.setLineDash([4,4]);ctx.beginPath();ctx.moveTo(p.l,y);ctx.lineTo(W-p.r,y);ctx.stroke();ctx.fillText(fmt(v,2),5,y+3)}for(let k=0;k<6;k++){let v=maxT*k/5;ctx.fillText(fmt(v,1),X(v)-8,H-12)}ctx.setLineDash([]);species.forEach((s,i)=>{ctx.strokeStyle=color(i);ctx.lineWidth=2.2;ctx.beginPath();result.pts.forEach((q,k)=>k?ctx.lineTo(X(q.t),Y(q.b[i])):ctx.moveTo(X(q.t),Y(q.b[i])));ctx.stroke()});if(result.stableTime!==null){ctx.strokeStyle="#d86d5b";ctx.setLineDash([5,4]);ctx.beginPath();ctx.moveTo(X(result.stableTime),p.t);ctx.lineTo(X(result.stableTime),H-p.b);ctx.stroke();ctx.setLineDash([])}}
function drawDonut(){let c=$("donut"),ctx=c.getContext("2d"),cx=110,cy=110,a=-Math.PI/2;ctx.clearRect(0,0,220,220);result.rel.forEach((v,i)=>{ctx.beginPath();ctx.arc(cx,cy,78,a,a+2*Math.PI*v);ctx.arc(cx,cy,43,a+2*Math.PI*v,a,true);ctx.closePath();ctx.fillStyle=color(i);ctx.fill();a+=2*Math.PI*v});ctx.fillStyle="#17324d";ctx.textAlign="center";ctx.font="bold 17px Georgia";ctx.fillText("100%",cx,cy-1);ctx.font="10px Arial";ctx.fillText("Community Composition",cx,cy+17)}
function sampleDist(d,c,s,lo,hi){if(d==="constant")return c;if(d==="uniform")return lo+Math.random()*(hi-lo);if(d==="lognormal"){s=Math.max(.001,s);let mu=Math.log(Math.max(c,1e-9))-.5*s*s;return clamp(Math.exp(mu+s*gauss()),lo,hi)}return clamp(c+Math.max(0,s)*gauss(),lo,hi)}
function randomize(){sync();let target=$("target").value,d=$("dist").value,c=num("center"),s=num("spread"),lo=num("minVal"),hi=num("maxVal"),pct=num("posPct");if(d==="direct"){setStatus("Direct-input mode: enter values in the parameter table below");return}if(!Number.isFinite(lo)||!Number.isFinite(hi)||lo>=hi)throw Error("The distribution lower bound must be less than the upper bound");if(target==="a")A=A.map((r,i)=>r.map((v,j)=>{if(i===j)return-1;if(d==="mixed"){let sign=Math.random()*100<pct?1:-1,mag=sampleDist("normal",Math.abs(c)||.18,s,Math.max(0,lo),Math.max(0,hi));return+(sign*Math.abs(mag)).toFixed(3)}return+sampleDist(d,c,s,lo,hi).toFixed(3)}));else{let floor=target==="b0"||target==="m"||target==="d"?0:.0001;species=species.map(q=>({...q,[target]:+Math.max(floor,sampleDist(d,c,s,Math.max(floor,lo),Math.max(floor+.000001,hi))).toFixed(8)}))}renderInputs();setStatus("Generated and populated parameters from the selected distribution")}
function batchSettings(){let target=$("target").value,d=$("dist").value,c=num("center"),s=num("spread"),lo=num("minVal"),hi=num("maxVal"),pct=num("posPct");if(d==="direct")throw Error("Select a random distribution for the target parameter before running repeated random simulations");if(!Number.isFinite(lo)||!Number.isFinite(hi)||lo>=hi)throw Error("DistributionLower Bound must be less than Upper Bound");if(!Number.isFinite(s)||s<0)throw Error("Standard Deviation must be nonnegative");if(d==="mixed"&&(!Number.isFinite(pct)||pct<0||pct>100))throw Error("The facilitation proportion must be between 0 and 100%");return{target,d,c,s,lo,hi,pct}}
function sampledModel(cfg){let sp=species.map(q=>({...q})),mat=A.map(r=>r.slice()),drawValue=()=>sampleDist(cfg.d,cfg.c,cfg.s,cfg.lo,cfg.hi);if(cfg.target==="a")mat=mat.map((r,i)=>r.map((v,j)=>{if(i===j)return-1;if(cfg.d==="mixed"){let sign=Math.random()*100<cfg.pct?1:-1,mag=sampleDist("normal",Math.abs(cfg.c)||.18,cfg.s,Math.max(0,cfg.lo),Math.max(0,cfg.hi));return sign*Math.abs(mag)}return drawValue()}));else sp=sp.map(q=>{let value,tries=0;do{value=drawValue();tries++}while(tries<200&&((cfg.target==="g"&&value<=q.m)||(cfg.target==="m"&&value>=q.g)));if(cfg.target==="b0"||cfg.target==="m"||cfg.target==="d")value=Math.max(0,value);else value=Math.max(.0001,value);if((cfg.target==="g"&&value<=q.m)||(cfg.target==="m"&&value>=q.g))throw Error("current Distributioncannot readily satisfy  r > m, Adjust Distributionrange");return{...q,[cfg.target]:value}});return{sp,mat}}
function simulateModel(sp,mat){let tm=Math.max(1,num("tMax")),sample=Math.max(.05,num("sample")),tol=Math.max(1e-8,num("tol")),x=sp.map(s=>Math.max(0,s.b0/s.k)),h=Math.max(.0005,Math.min(.05,sample/5,tm/3000)),t=0,next=sample,pts=[{t:0,b:x.map((v,i)=>v*sp[i].k)}],stableStart=null,stableTime=null,window=Math.max(sample*3,Math.min(10,tm*.1)),warning="";let derivative=y=>y.map((yi,i)=>{let z=1;for(let j=0;j<N;j++)z+=mat[i][j]*y[j];return sp[i].g*yi*z-sp[i].m*yi+(sp[i].d??0)}),stepRK=(y,dt)=>{let k1=derivative(y),k2=derivative(y.map((v,i)=>v+dt*k1[i]/2)),k3=derivative(y.map((v,i)=>v+dt*k2[i]/2)),k4=derivative(y.map((v,i)=>v+dt*k3[i]));return y.map((v,i)=>clamp(v+dt*(k1[i]+2*k2[i]+2*k3[i]+k4[i])/6,0,1e6))};while(t<tm-1e-10){let step=Math.min(h,tm-t);x=stepRK(x,step);t+=step;if(x.some(v=>!Number.isFinite(v)||v>=999999)){warning="unbounded";break}let d=derivative(x),ok=Math.max(...d.map(Math.abs))/Math.max(1,...x)<tol;if(ok){if(stableStart===null)stableStart=t;if(stableTime===null&&t-stableStart>=window)stableTime=stableStart}else stableStart=null;if(t+1e-8>=next||t+1e-8>=tm){pts.push({t:Math.min(t,tm),b:x.map((v,i)=>v*sp[i].k)});next+=sample}}return{pts,stableTime,warning}}
function csvCell(v){let s=String(v==null?"":v);return/[",\n]/.test(s)?'"'+s.replace(/"/g,'""')+'"':s}
async function saveCSV(text,name){let blob=new Blob(["\ufeff"+text],{type:"text/csv;charset=utf-8"}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=name;a.style.display="none";document.body.appendChild(a);a.click();setTimeout(()=>{a.remove();URL.revokeObjectURL(url)},1000);return"The file has been submitted to the browser download folder"}
async function runBatch(){if(mode!=="known")throw Error("Switch to the Known-Parameter Model tab to run repeated random simulations");resizeModel(false);sync();validate();let cfg=batchSettings(),count=Math.round(num("batchCount"));if(!Number.isFinite(count)||count<2||count>1000)throw Error("The number of random simulations must be an integer between 2 and 1000");let button=$("batchBtn"),progress=$("batchProgress"),summary=$("batchSummary"),records=[],unbounded=0,seen=new Set(),signature=model=>cfg.target==="a"?model.mat.flat().map(v=>Number(v).toPrecision(12)).join("|"):model.sp.map(s=>Number(s[cfg.target]).toPrecision(12)).join("|");button.disabled=true;button.textContent="Simulating…";try{for(let run=1;run<=count;run++){let model,key,attempt=0;do{model=sampledModel(cfg);key=signature(model);attempt++}while(seen.has(key)&&attempt<100);if(seen.has(key))throw Error("The current distribution produced duplicate parameter sets; increase the standard deviation or value range and try again");seen.add(key);let sim=simulateModel(model.sp,model.mat),param=[];model.sp.forEach((s,i)=>param.push([`S${i+1}_name`,s.name],[`S${i+1}_B0`,s.b0],[`S${i+1}_r`,s.g],[`S${i+1}_m`,s.m],[`S${i+1}_K`,s.k],[`S${i+1}_D`,s.d??0]));for(let i=0;i<N;i++)for(let j=0;j<N;j++)param.push([`a${i+1}_${j+1}`,model.mat[i][j]]);if(sim.warning)unbounded++;records.push({run,sim,param});progress.style.width=(run/count*100)+"%";summary.textContent=`Simulating: ${run} / ${count}`;if(run%5===0)await new Promise(resolve=>setTimeout(resolve,0))}let paramNames=records[0].param.map(q=>q[0]),head=["run","status","stable_time","time",...species.map((s,i)=>`S${i+1}_${s.name}_B`),...paramNames],rows=[head.map(csvCell).join(",")];records.forEach(rec=>rec.sim.pts.forEach(pt=>rows.push([rec.run,rec.sim.warning||"ok",rec.sim.stableTime==null?"":rec.sim.stableTime,pt.t,...pt.b,...rec.param.map(q=>q[1])].map(csvCell).join(","))));let stamp=new Date().toISOString().replace(/[:.]/g,"-").slice(0,19),message=await saveCSV(rows.join("\n"),`glv_random_simulations_${count}_${stamp}.csv`);summary.textContent=`Completed ${count} simulations (${unbounded} with unbounded growth); ${message}`;setStatus(`Repeated random simulation completed: ${count} runs; CSV generated`)}finally{button.disabled=false;button.textContent="Run and Save CSV"}}
const targetInfo={b0:{name:"Initial Biomass B₀",meaning:"at simulation start Species actual Biomass; must ≥ 0, units should match  K consistent.",defaults:[.08,.02,.01,.2]},g:{name:"Growth Rate r",meaning:"intrinsic value in the growth termGrowth Rate, units: Time⁻¹;  must be greater than Mortality Rate m.",defaults:[.6,.1,.1,1.2]},m:{name:"Mortality Rate m",meaning:"independent loss term −mᵢxᵢ  Mortality Rate, units: Time⁻¹; is not multiplied by Interactionsterm, and must satisfy  0 ≤ m < r.",defaults:[.05,.015,0,.15]},k:{name:"baseline environmentCarrying Capacity K",meaning:"without mortality when  monocultureCarrying Capacityand dimensionlessnormalization scale; with mortality when monoculturestable Biomass is  K(1−m/r).",defaults:[1,.2,.2,2]},d:{name:"Immigration Rate D",meaning:"external Speciespool to each Species continuous additive Input, units: normalized Biomass·Time⁻¹; must ≥ 0, D=0 restores no immigration when Model.",defaults:[.000001,.0000002,0,.00001]},a:{name:"Interactions aᵢⱼ",meaning:"dimensionless; columnSpecies j  for rowSpecies i  interaction.aᵢⱼ > 0  is Facilitation, < 0  is Inhibition, diagonal fixed at  −1.",defaults:[0,.18,-.6,.6]}};
function updateDistributionUI(resetTarget=false){let target=$("target").value,d=$("dist").value,info=targetInfo[target];Array.from($("dist").options).forEach(o=>{let valid=target==="a"?o.value!=="lognormal":o.value!=="mixed";o.hidden=!valid;o.disabled=!valid});if((target==="a"&&d==="lognormal")||(target!=="a"&&d==="mixed")){d="direct";$("dist").value=d}if(resetTarget){let q=info.defaults;$("center").value=q[0];$("spread").value=q[1];$("minVal").value=q[2];$("maxVal").value=q[3];d="direct";$("dist").value=d}let show=(id,on)=>$(id).classList.toggle("hidden",!on);show("centerField",d!=="uniform"&&d!=="direct");show("spreadField",d==="normal"||d==="lognormal"||d==="mixed");show("minField",d!=="direct");show("maxField",d!=="direct");show("posField",d==="mixed");show("randomBtn",d!=="direct");$("centerLabel").textContent=d==="mixed"?"absolute Interaction StrengthMean μ":"arithmetic Mean μ";$("spreadLabel").textContent=d==="lognormal"?"log-scale Standard Deviation σlog":"Standard Deviation σ";$("minLabel").textContent=d==="mixed"?"Minimum Absolute Strength":"value Lower Bound L";$("maxLabel").textContent=d==="mixed"?"Maximum Absolute Strength":"value Upper Bound U";if(d==="mixed"&&num("minVal")<0)$("minVal").value=0;if((d==="lognormal"||target!=="a")&&num("minVal")<0)$("minVal").value=(target==="b0"||target==="m"||target==="d")?0:.0001;let text={direct:`No random Distribution.Directly enter values in the Parameterstable item by itemInputor modify them${info.name}; Current table values are used at runtime.`,uniform:`X ~ U(L,U): ${info.name}in Lower Bound L  and Upper Bound U ; All values within the interval are equally likely.`,normal:`X ~ N(μ,σ²), and truncated to  [L,U]: μ controls Distribution Center, σ controls dispersion, exceeds above Lower Bound values are clipped to the boundary.`,lognormal:`X follows Truncated LognormalDistribution: The entered  μ is the target arithmetic mean, σlog controls right-skewness; applies only to strictly nonnegative Parameters.`,mixed:`First use ‘Facilitation Proportion’to determine the sign, then from Truncated Normal Distributionsample the absolute Interaction Strength; suitable for simultaneously containing Facilitation and Inhibition relationships in the Matrix.`}[d];$("distHelp").innerHTML=`<b>${info.name}</b>: ${info.meaning}<br><b>Current Input Method</b>: ${text}`}
function monoPrediction(r,m,x0,t){let q=r-m,L=q/r;return L/(1+(L/x0-1)*Math.exp(-q*t))}
function fitIntrinsicRate(s,t){if(!Number.isFinite(s.m)||s.m<0)throw Error(`${s.name}  Mortality Rate m  must be nonnegative`);let x0=s.b0/s.k,xt=s.bMid/s.k;if(!(x0>0&&x0<1&&xt>0&&xt<1))throw Error(`${s.name}  must satisfy  0 < B₀, B(tₘ) < K`);let lo=s.m+1e-8,hi=Math.max(1,s.m+1),fLo=monoPrediction(lo,s.m,x0,t)-xt;if(fLo>0)throw Error(`${s.name}   B(tₘ) is too low, Cannot fit under  r > m  conditions`);while(monoPrediction(hi,s.m,x0,t)<xt&&hi<1e4)hi*=2;if(hi>=1e4&&monoPrediction(hi,s.m,x0,t)<xt)throw Error(`${s.name} Cannot fit a finite Growth Rate r`);for(let n=0;n<80;n++){let mid=(lo+hi)/2;if(monoPrediction(mid,s.m,x0,t)<xt)lo=mid;else hi=mid}return(hi+lo)/2}
function fit(){sync();let t=Math.max(.01,num("midTime"));species=species.map(s=>({...s,g:+fitIntrinsicRate(s,t).toFixed(5)}));A=A.map((r,i)=>r.map((v,j)=>{if(i===j)return-1;let xi=pairs[i][j]/species[i].k,xj=pairs[j][i]/species[j].k,ci=1-species[i].m/species[i].g;return+(xj>1e-9?(xi-ci)/xj:0).toFixed(4)}));fitReady=true;renderInputs();setStatus("Fitting completed: r and the interaction matrix were generated; mortality remains an independent loss term in simulation and export")}
function setMode(m){sync();mode=m;$("knownPanel").classList.toggle("hidden",m!=="known");$("fitPanel").classList.toggle("hidden",m!=="fit");$("knownTab").classList.toggle("active",m==="known");$("fitTab").classList.toggle("active",m==="fit");$("modeTitle").textContent=m==="known"?"Known-Parameter Settings":"Experimental-Data Fitting";renderInputs()}
function setStatus(t){$("status").textContent="● "+t}
function resizeModel(announce=true){sync();let requested=Math.round(num("nInput"));if(!Number.isFinite(requested)||requested<1||requested>20)throw Error("Number of Species N must is  1–20 an integer in the range ");if(requested===N)return false;let oldSpecies=species,oldA=A;N=requested;$("nInput").value=N;let defaults=makeSpecies(N),defaultA=makeA(N);species=Array.from({length:N},(_,i)=>oldSpecies[i]?{...defaults[i],...oldSpecies[i],d:Number.isFinite(oldSpecies[i].d)?oldSpecies[i].d:0}:defaults[i]);A=Array.from({length:N},(_,i)=>Array.from({length:N},(_,j)=>i===j?-1:(oldA[i]&&Number.isFinite(oldA[i][j])?oldA[i][j]:defaultA[i][j])));pairs=makePairs();fitReady=false;renderInputs();if(announce)setStatus(`Applied N = ${N}; the parameter table and matrix were rebuilt safely`);return true}
function paintMatrixInput(el){let [i,j]=el.dataset.a.split(",").map(Number),v=Number(el.value);if(i===j||!A[i]||j>=A[i].length)return;A[i][j]=v;let alpha=Math.min(.75,Math.abs(v));el.parentElement.style.background=v>0?`rgba(23,63,103,${.08+alpha*.5})`:`rgba(216,109,91,${.08+alpha*.5})`}
function paintFittedMatrixInput(el){let [i,j]=el.dataset.fra.split(",").map(Number),v=Number(el.value);if(i===j||!A[i]||j>=A[i].length)return;A[i][j]=v;let alpha=Math.min(.75,Math.abs(v));el.parentElement.style.background=v>0?`rgba(23,63,103,${.08+alpha*.5})`:`rgba(216,109,91,${.08+alpha*.5})`}
async function exportCSV(){if(!result)simulate();let sp=species.map(s=>({...s})),mat=A.map(r=>r.slice()),params=[];sp.forEach((s,i)=>params.push([`S${i+1}_name`,s.name],[`S${i+1}_B0`,s.b0],[`S${i+1}_r`,s.g],[`S${i+1}_m`,s.m],[`S${i+1}_K`,s.k],[`S${i+1}_D`,s.d??0]));for(let i=0;i<N;i++)for(let j=0;j<N;j++)params.push([`a${i+1}_${j+1}`,mat[i][j]]);let head=["simulation_id","status","stable_time","time",...sp.map((s,i)=>`S${i+1}_${s.name}_B`),...params.map(q=>q[0])],rows=[head.map(csvCell).join(",")];result.pts.forEach(q=>rows.push([1,result.warning||"ok",result.stableTime==null?"":result.stableTime,q.t,...q.b,...params.map(p=>p[1])].map(csvCell).join(",")));let stamp=new Date().toISOString().replace(/[:.]/g,"-").slice(0,19),message=await saveCSV(rows.join("\n"),`glv_single_simulation_${stamp}.csv`);setStatus(`single  simulations CSV Generated; ${message}`)}
function safely(fn){try{fn()}catch(e){console.error(e);setStatus("Input error: "+(e&&e.message?e.message:"Check the parameters"));$("status").classList.add("warning")}}
async function safelyAsync(fn){try{await fn()}catch(e){console.error(e);if(e&&e.name==="AbortError"){setStatus("Save canceled CSV");return}setStatus("Input error: "+(e&&e.message?e.message:"Check the parameters"));$("status").classList.add("warning")}}
document.addEventListener("input",e=>{let el=e.target;if(el.matches("[data-a]"))paintMatrixInput(el);else if(el.matches("[data-s]")){let i=+el.dataset.s,key=el.dataset.key;if(species[i])species[i][key]=key==="name"?el.value:Number(el.value)}else if(el.matches("[data-exp]")){let i=+el.dataset.exp,key=el.dataset.key;if(species[i])species[i][key]=key==="name"?el.value:Number(el.value);fitReady=false;$("fitResultPanel").classList.add("hidden")}else if(el.matches("[data-p]")){let [i,j]=el.dataset.p.split(",").map(Number);if(i!==j&&pairs[i]&&j<pairs[i].length)pairs[i][j]=Number(el.value);fitReady=false;$("fitResultPanel").classList.add("hidden")}else if(el.matches("[data-frs]")){let i=+el.dataset.frs,key=el.dataset.key;if(species[i])species[i][key]=key==="name"?el.value:Number(el.value)}else if(el.matches("[data-fra]"))paintFittedMatrixInput(el);if(el.id==="midTime"){fitReady=false;$("fitResultPanel").classList.add("hidden")}if(el.matches("input,select")){$("status").classList.remove("warning");setStatus(el.id==="nInput"?"Number of Specieschanged: Click ‘Apply N’or run directly":"Parameterschanged: Click ‘Run Simulation’Updatesresults")}});window.addEventListener("error",e=>setStatus("Runtime error: "+(e.message||"Check the input parameters")));
$("knownTab").onclick=()=>safely(()=>setMode("known"));$("fitTab").onclick=()=>safely(()=>setMode("fit"));$("runBtn").onclick=()=>safely(()=>{let changed=resizeModel(false);if(mode==="fit"&&!fitReady)throw Error("Experimental data changed, First CompletedParameter fitting");simulate();if(changed)setStatus(`Rebuilt the model with N = ${N} and completed the simulation`)});$("exportBtn").onclick=()=>safelyAsync(exportCSV);$("randomBtn").onclick=()=>safely(randomize);$("batchBtn").onclick=()=>safelyAsync(runBatch);$("fitBtn").onclick=()=>safely(fit);$("resizeBtn").onclick=()=>safely(()=>{let changed=resizeModel(true);if(changed&&mode==="known")simulate();else if(!changed)setStatus(`The current value is already  N = ${N}`)});$("target").onchange=()=>updateDistributionUI(true);$("dist").onchange=()=>updateDistributionUI(false);
